import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { apigatewayApiConfigFileSchema, type ApigatewayApiConfigFile } from "./apigateway-api-config-file.js";
import {
  apigatewayApiConfigFile1Schema,
  type ApigatewayApiConfigFile1,
} from "./apigateway-api-config-file1.js";

/** A gRPC service definition. */
export type ApigatewayApiConfigGrpcServiceDefinition = {
  /**
   * Input only. File descriptor set, generated by protoc. To generate, use protoc with imports and
   * source info included. For an example test.proto file, the following command would put the value
   * in a new file named out.pb. $ protoc --include_imports --include_source_info test.proto -o
   * out.pb
   */
  fileDescriptorSet?: ApigatewayApiConfigFile1;
  /**
   * Optional. Uncompiled proto files associated with the descriptor set, used for display purposes
   * (server-side compilation is not supported). These should match the inputs to 'protoc' command
   * used to generate file_descriptor_set.
   */
  source?: ApigatewayApiConfigFile[];
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const apigatewayApiConfigGrpcServiceDefinitionSchema: Schema<ApigatewayApiConfigGrpcServiceDefinition> =
  s.object<ApigatewayApiConfigGrpcServiceDefinition>(
    {
      fileDescriptorSet: s.optional(s.lazy(() => apigatewayApiConfigFile1Schema)),
      source: s.optional(s.array(s.lazy(() => apigatewayApiConfigFileSchema))),
    },
    { additionalProperties: s.json() },
  );
